(()=>{const logos={"BTC": "assets/btc.png", "ETH": "assets/eth.png", "USDC": "assets/usdc.png", "XRP": "assets/xrp.png", "SOL": "assets/sol.png", "DOGE": "assets/doge.png", "LINK": "assets/link.png", "ADA": "assets/ada.png", "NEAR": "assets/near.jpg", "BCH": "assets/bch.png", "LTC": "assets/ltc.png", "AVAX": "assets/avax.png", "UNI": "assets/uni.png", "SUI": "assets/sui.png", "AAVE": "assets/aave.png", "PEPE": "assets/pepe.jpg", "DOT": "assets/dot.jpg", "ARB": "assets/arb.jpg", "BONK": "assets/bonk.jpg", "OP": "assets/op.png", "WIF": "assets/wif.jpg", "NVDA": "assets/nvda.png", "TSLA": "assets/tsla.png", "AAPL": "assets/aapl.png", "MSFT": "assets/msft.png", "AMZN": "assets/amzn.png", "GOOGL": "assets/googl.png", "META": "assets/meta.png", "NFLX": "assets/nflx.png", "AMD": "assets/amd.png", "INTC": "assets/intc.png", "COIN": "assets/coin.png", "PLTR": "assets/pltr.png", "MSTR": "assets/mstr.png", "JPM": "assets/jpm.png", "V": "assets/v.png", "DIS": "assets/dis.png", "WMT": "assets/wmt.png", "UBER": "assets/uber.png", "SPY": "assets/spy.png"};
const vectors={"NVDA": "assets/nvda-mark.svg", "TSLA": "assets/tsla-mark.svg", "AAPL": "assets/aapl-mark.svg", "GOOGL": "assets/googl-mark.svg", "META": "assets/meta-mark.svg", "NFLX": "assets/nflx-mark.svg", "AMD": "assets/amd-mark.svg", "INTC": "assets/intc-mark.svg", "COIN": "assets/coin-mark.svg", "PLTR": "assets/pltr-mark.svg", "MSTR": "assets/mstr-mark.svg", "JPM": "assets/jpm-mark.svg", "V": "assets/v-mark.svg", "UBER": "assets/uber-mark.svg", "MSFT": "assets/msft-mark.svg", "AMZN": "assets/amzn-mark.svg", "WMT": "assets/wmt-mark.svg"};const brandColors={"NVDA": "#76b900", "TSLA": "#e82127", "GOOGL": "#4285f4", "META": "#0866ff", "NFLX": "#e50914", "COIN": "#1652f0", "V": "#4465b4"};
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const graphic=(path,cls='ui-icon')=>`<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${path}</svg>`;
function token(symbol,name=symbol){const path=logos[symbol],vector=vectors[symbol];return `<span class="coin asset-logo ${vector?'vector-logo':''}">${vector?`<span class="brand-mark" style="--mark:url('${vector}');--brand-color:${brandColors[symbol]||'var(--text)'}" aria-hidden="true"></span>`:path?`<img src="${path}" alt="" decoding="async" width="36" height="36">`:`<span>${esc(symbol.slice(0,2))}</span>`}</span>`}
function network(name){const symbol=name.startsWith('Zero')?'ZERO':name.includes('Arbitrum')?'ARB':name==='Base'?'BASE':'ETH';return symbol==='BASE'?'<span class="coin asset-logo base-logo"><svg viewBox="0 0 32 32" aria-hidden="true"><circle cx="16" cy="16" r="16" fill="#0052ff"/><path d="M6 16h20" stroke="white" stroke-width="2.5"/></svg></span>':token(symbol)}
const sun=graphic('<circle cx="12" cy="12" r="3.5"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.4 1.4m11.2 11.2L19 19M5 19l1.4-1.4M17.6 6.4 19 5"/>');
const moon=graphic('<path d="M20.5 14A8.6 8.6 0 0 1 10 3.5 8.7 8.7 0 1 0 20.5 14Z"/>');
const reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
function enter(el){if(el&&!reduced())el.animate([{opacity:.45,transform:'translateY(9px)'},{opacity:1,transform:'translateY(0)'}],{duration:300,easing:'cubic-bezier(.2,.8,.2,1)'})}
document.addEventListener('error',e=>{const image=e.target;if(image.tagName==='IMG'&&image.closest('.asset-logo')){const wrap=image.parentElement;image.remove();wrap.classList.add('logo-unavailable');wrap.innerHTML=graphic('<circle cx="12" cy="12" r="7"/><path d="M9 12h6"/>')}},true);
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b||b.disabled||reduced())return;b.animate([{transform:'scale(.96)',filter:'brightness(.92)'},{transform:'scale(1)',filter:'brightness(1)'}],{duration:190,easing:'ease-out'})},true);

const leaf=graphic('<path d="M4 19C4 9 11 3 21 3c0 10-6 17-16 17M5 19 17 7M8 15h7M12 11V6"/>','falling-leaf');
function progress(label,detail=''){return `<div class="transaction-progress" role="status"><div class="leaf-stage" aria-hidden="true"><div class="leaf-drift">${leaf}</div><span class="leaf-shadow"></span></div><h3>${esc(label)}</h3><p>${esc(detail)}</p></div>`}
let indicatorTimer;
function transaction(label,active=true,outcome='success'){let el=document.querySelector('#transaction-indicator');if(!el){el=document.createElement('div');el.id='transaction-indicator';el.setAttribute('role','status');document.body.append(el)}clearTimeout(indicatorTimer);el.dataset.outcome=outcome;el.innerHTML=`${active?`<span class="small-leaf">${leaf}</span>`:outcome==='error'?graphic('<path d="m7 7 10 10M17 7 7 17"/>'):graphic('<path d="m5 12 4 4L19 6"/>')}<span>${esc(label)}</span>`;el.classList.add('visible');if(!active)indicatorTimer=setTimeout(()=>el.classList.remove('visible'),5000)}

window.CanopyUI={progress,transaction,token,network,graphic,sun,moon,enter,logos};})();
